    "annotations": {
      "muster/openapi-method": "POST",
      "muster/openapi-path": "/v1/bridge/crier/messages"
    },
    "description": "Adapter verifies peer mapping and digest before local commit. Request/delivery dedupe result is committed with local record. Application ACK only after durable readback; transport inbox ACK afterwards. as=vp is specifically peer_vp_claim, not a permissive role override. This local adapter endpoint requires a service:bridge-adapter credential. Remote peers cannot submit transport_receipt or lease authority. Adapter independently authenticates/maps the source before posting.",
    "inputSchema": {
      "properties": {
        "correlation_id": {
          "type": "string"
        },
        "dedupe_key": {
          "type": "string"
        },
        "envelope": {
          "description": "Proposed NETWORK projection, not replacement for BridgeLedgerEnvelope. Sender emits outbound_delivery or outbound_ack; receiver derives inbound_data plus local lease in its ledger. Transport lease never trusted from peer. Digest binds payload only. Added typed payload and required identity/time fields are profile decisions.",
          "type": "object"
        },
        "request_id": {
          "type": "string"
        },
        "transport_receipt": {
          "type": "object"
        }
